import {normalize,checkAnswer,makeChoices,makeSession,restoreProgress,recordAnswer,restoreSession} from './core.mjs';
import {offlineStatus,downloadAll,cancelDownload} from './offline.js';
const icons={practice:'<path d="m8 4 12 8-12 8V4Z"/>',dictionary:'<path d="M12 5v15M3 4h5q4 0 4 3 0-3 4-3h5v15h-5q-4 0-4 2 0-2-4-2H3V4Z"/>',offline:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',speaker:'<path d="m11 4-5 4H3v8h3l5 4V4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[name]+'</svg>';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=document.querySelector('#main'),status=document.querySelector('#status');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('sp-'+key))??fallback;}catch{return fallback;}};
const save=(key,value)=>{try{localStorage.setItem('sp-'+key,JSON.stringify(value));}catch{status.textContent='Storage is unavailable. Progress will last only while this page stays open.';}};
let data,manifest,progress={},bookmarks=new Set(),settings={module:'1',section:'all',mode:'recognition',review:false},session=null,query='',onlyBookmarks=false,audio=null,downloadBusy=false,downloadState=null,offlineError='',installPrompt=null;
const byId=new Map();
const modeNames={recognition:'Choose the translation.',spelling:'Write the English word.',listening:'Listen and choose.'};
const currentEntry=()=>session&&byId.get(session.ids[session.position]);
const currentResponse=()=>session.responses[session.position]||(session.responses[session.position]={answer:'',checked:false,correct:false,assisted:false,recorded:false,revealed:false});
function stopAudio(){if(audio){audio.pause();audio.removeAttribute('src');audio.load();audio=null;}document.querySelectorAll('.speaker').forEach(b=>{b.classList.remove('playing');b.setAttribute('aria-pressed','false');});}
function persistSession(){save('session',session);}
function selectEntries(review=settings.review){return data.entries.filter(e=>(settings.module==='all'||String(e.module)===settings.module)&&(settings.section==='all'||e.sectionId===settings.section)&&(!review||progress[e.id]?.needsReview)&&(!onlyBookmarks||bookmarks.has(e.id)));}
function speaker(e,concealed=false){return '<button type="button" class="speaker" data-speak="'+esc(e.id)+'" aria-label="'+(concealed?'Listen to the English word':'Listen: '+esc(e.word))+'" aria-pressed="false">'+icon('speaker')+'</button>';}
function sectionsHTML(){const modules=data.modules.filter(m=>settings.module==='all'||String(m.id)===settings.module);return '<option value="all">All lessons</option>'+modules.flatMap(m=>m.sections.map(s=>'<option value="'+esc(s.id)+'" '+(settings.section===s.id?'selected':'')+'>'+esc(s.label.replace(' — слова','').replace(' — Phrasals & Phrases',' · phrases'))+'</option>')).join('');}
function filtersHTML(){return '<div class="form-grid"><label class="field">Module<select id="module"><option value="all" '+(settings.module==='all'?'selected':'')+'>Modules 1 + 2</option>'+data.modules.map(m=>'<option value="'+m.id+'" '+(settings.module===String(m.id)?'selected':'')+'>'+m.id+' · '+m.title+'</option>').join('')+'</select></label><label class="field">Lesson<select id="section">'+sectionsHTML()+'</select></label></div>';}
function renderHome(){main.className='';const pool=selectEntries();const learned=data.entries.filter(e=>progress[e.id]?.correct>0&&!progress[e.id]?.needsReview).length;const reviewCount=data.entries.filter(e=>progress[e.id]?.needsReview).length;main.innerHTML='<h1>A few words. Every day.</h1><p class="intro" lang="ru">Слова Spotlight 8 для короткой тренировки в дороге.</p>'+filtersHTML()+'<label class="field">Practice mode</label><div class="modes">'+[['recognition','Translate','EN → RU'],['spelling','Write','RU → EN'],['listening','Listen','Audio → RU']].map(([value,label,sub])=>'<button class="mode '+(settings.mode===value?'active':'')+'" data-mode="'+value+'" aria-pressed="'+(settings.mode===value)+'"><strong>'+label+'</strong>'+sub+'</button>').join('')+'</div><label class="check-row"><input id="review-only" type="checkbox" '+(settings.review?'checked':'')+'>Practise mistakes only</label>'+(onlyBookmarks?'<p class="muted">Showing bookmarked words. <button class="text-button" data-action="unfilter">Show all</button></p>':'')+'<button class="button wide" data-action="start" '+(!pool.length?'disabled':'')+'>'+icon('practice')+'Start · '+Math.min(10,pool.length)+' words</button>'+(session?'<button class="button secondary wide" style="margin-top:10px" data-action="resume">Continue saved session</button>':'')+(!pool.length?'<p class="empty">No words match these filters. Change the lesson or switch off the filter.</p>':'')+'<div class="stats"><div class="stat"><strong>'+learned+'</strong><span>learned</span></div><div class="stat"><strong>'+reviewCount+'</strong><span>to review</span></div><div class="stat"><strong>686</strong><span>words & phrases</span></div></div><a href="#offline">Save words and audio for your next trip '+icon('offline')+'</a>';}
function renderPractice(){if(!session){renderHome();return;}if(session.position>=session.ids.length){renderResult();return;}const e=currentEntry(),r=currentResponse();main.className='training'+(r.checked&&r.correct?' answered':'');if(!e){session=null;persistSession();renderHome();return;}const concealed=session.mode==='listening';const spelling=session.mode==='spelling';main.innerHTML='<div class="progress-top"><span>'+(session.position+1)+' / '+session.ids.length+'</span><button class="text-button" data-action="home">Pause</button></div><progress max="'+session.ids.length+'" value="'+session.position+'" aria-label="Session progress"></progress><p class="section-label">Module '+e.module+' · '+esc(e.sectionId)+'</p><h1>'+modeNames[session.mode]+'</h1><div class="word-row">'+(concealed?'<span class="word">Listen first</span>':'<span class="word" lang="'+(spelling?'ru':'en')+'">'+esc(spelling?e.meaning:e.word)+'</span>')+speaker(e,concealed||spelling)+'</div><p class="caption">'+(spelling?'Example: type a word or a phrase. Audio gives a hint.':concealed?'Play the word, then choose its meaning.':'Listen and choose.')+'</p>'+(spelling?'<form id="answer-form"><label class="field" for="answer">Your answer</label><input class="answer" id="answer" value="'+esc(r.answer)+'" placeholder="Type in English" autocomplete="off" autocapitalize="none" spellcheck="false" enterkeyhint="done"><button class="button wide" type="submit" '+(!r.answer.trim()?'disabled':'')+'>Check answer</button></form><button class="text-button" data-action="reveal">'+(r.revealed?'Hide answer':'Show answer')+'</button>': '<div class="choices">'+session.choices[session.position].map((c,i)=>'<button class="choice '+(r.checked?(c.correct?'correct':r.answer===String(i)?'wrong':''):'')+'" data-choice="'+i+'" '+(r.checked?'disabled':'')+' lang="ru">'+esc(c.text)+'</button>').join('')+'</div>')+(r.revealed?'<p class="feedback" lang="en">'+esc(e.answers.join(' / '))+'</p>':'')+(r.checked?'<div class="feedback '+(r.correct?'good':'bad')+'" role="status">'+(r.correct?(r.assisted?'Correct with help. Keep practising.':'Correct. Well done.'):'Keep this one for review.')+'<br><strong lang="en">'+esc(e.word)+'</strong> — <span lang="ru">'+esc(e.meaning)+'</span>'+(spelling&&!r.correct?'<br>Accepted: '+esc(e.answers.join(' / ')):'')+'</div><button class="button wide" data-action="next">'+(session.position+1===session.ids.length?'See results':'Next word')+'</button>':'')+'<div class="actions"><button class="text-button" data-action="bookmark">'+(bookmarks.has(e.id)?'Remove bookmark':'Bookmark word')+'</button><button class="text-button" data-action="skip">Skip for review</button></div>';}
function renderResult(){main.className='';const responses=Object.values(session.responses);const correct=responses.filter(r=>r.correct&&!r.assisted).length;const mistakes=session.ids.filter((id,i)=>!session.responses[i]?.correct||session.responses[i]?.assisted);main.innerHTML='<h1>Session complete.</h1><p class="intro">Small steps add up.</p><p class="result-score">'+correct+' / '+session.ids.length+'</p><p class="muted">correct without help</p><div class="actions"><button class="button" data-action="finish">Back to practice</button>'+(mistakes.length?'<button class="button secondary" data-action="retry">Review '+mistakes.length+' words</button>':'')+'</div>'+(mistakes.length?'<h2>Another look</h2>'+mistakes.map(id=>{const e=byId.get(id);return '<div class="dictionary-row"><div class="entry"><strong lang="en">'+esc(e.word)+'</strong><p lang="ru">'+esc(e.meaning)+'</p></div>'+speaker(e)+'</div>';}).join(''):'<p class="feedback good">All words answered independently.</p>');}
function renderDictionary(){main.className='';const all=selectEntries(false).filter(e=>!query||normalize(e.word+' '+e.meaning+' '+e.translations.join(' ')).includes(normalize(query)));main.innerHTML='<h1>Your wordbook.</h1><p class="intro">Listen, look up, come back to it.</p>'+filtersHTML()+'<label class="field">Find a word<input class="search" id="search" type="search" placeholder="English or Russian" value="'+esc(query)+'"></label><label class="check-row"><input id="bookmarks-only" type="checkbox" '+(onlyBookmarks?'checked':'')+'>Bookmarked words only</label><p class="muted">'+all.length+' entries</p><div class="word-list">'+all.slice(0,120).map(e=>'<article class="dictionary-row"><div class="entry"><strong lang="en">'+esc(e.word)+'</strong><p lang="ru">'+esc(e.meaning)+'</p><small>Module '+e.module+' · '+esc(e.sectionId)+' · '+esc(e.partOfSpeech)+'</small></div><button class="icon-button '+(bookmarks.has(e.id)?'marked':'')+'" data-bookmark="'+esc(e.id)+'" aria-label="'+(bookmarks.has(e.id)?'Remove bookmark: ':'Bookmark: ')+esc(e.word)+'" aria-pressed="'+bookmarks.has(e.id)+'">'+icon('bookmark')+'</button>'+speaker(e)+'</article>').join('')+'</div>'+(all.length>120?'<p class="muted">Showing 120 entries. Choose a lesson or search to narrow the list.</p>':'')+(!all.length?'<p class="empty">No matching words.</p>':'');}
async function renderOffline(){main.className='';main.innerHTML='<h1>Ready for the road.</h1><p class="intro" lang="ru">Скачайте слова и произношение, пока есть интернет.</p><div id="download-box" class="offline-state">Checking saved files…</div><h2>Add to your home screen</h2><ol class="steps" lang="ru"><li><strong>iPhone:</strong> откройте ссылку в Safari → «Поделиться» → «На экран Домой».</li><li><strong>Android:</strong> откройте в Chrome → меню ⋮ → «Добавить на главный экран» или «Установить приложение».</li><li>Откройте сайт с главного экрана и нажмите <strong>Download for offline</strong>. Дождитесь статуса <strong>Ready offline</strong>.</li><li>Перед поездкой включите авиарежим и проверьте слово с озвучкой.</li></ol><div id="install-area"></div><details><summary>About audio and saved progress</summary><p lang="ru">686 словарных записей Spotlight 8, модули 1 и 2, с отдельными значениями и выражениями. Произношение — готовые синтезированные записи Microsoft Zira (английский США), перенесённые из локального проекта Spotlight.</p><p lang="ru">Пакет озвучки — около 50 МБ. Открывайте сайт обычным браузером: приватный режим и очистка данных удаляют сохранения. Прогресс хранится отдельно в каждом браузере и на каждом устройстве. Браузер может освободить место при нехватке памяти; перед поездкой проверьте готовность пакета. Сайт не оценивает произношение ученика.</p></details>';await refreshOffline();if(location.hash==='#offline'&&installPrompt)document.querySelector('#install-area').innerHTML='<button class="button secondary" data-action="install">Install app</button>';}
function downloadBox(){const box=document.querySelector('#download-box');if(!box)return;const s=downloadState;const ready=s?.shell&&s.count===s.total;if(downloadBusy&&box.querySelector('[data-action="cancel-download"]')){const bar=box.querySelector('progress');if(bar&&s){bar.value=s.count;bar.max=s.total;}const label=box.querySelector('p');if(label&&s)label.textContent=s.count+' / '+s.total+' audio files · '+(s.shell?'wordbook saved':'wordbook preparing');return;}box.innerHTML='<strong>'+(ready?'Ready offline':downloadBusy?'Saving for your trip…':s?.count?'Download paused':'Save your travel pack')+'</strong><p>'+(s?(s.count+' / '+s.total+' audio files · '+(s.shell?'wordbook saved':'wordbook preparing')):'Preparing offline storage…')+'</p>'+(s?'<progress value="'+s.count+'" max="'+s.total+'" aria-label="Audio download"></progress>':'')+(offlineError?'<p role="alert">'+esc(offlineError)+'</p>':'')+(downloadBusy?'<button class="button secondary wide" data-action="cancel-download">Pause download</button>':ready?'<button class="button secondary wide" data-action="verify-offline">Check saved files</button>':'<button class="button wide" data-action="download">'+(s?.count?'Resume download':'Download for offline')+'</button>')+'<p style="font-size:13px;margin-bottom:0" lang="ru">'+(ready?'Слова и все записи сохранены. Можно тренироваться без сети.':'Около 50 МБ. Во время скачивания держите страницу открытой. Уже скачанные файлы сохранятся.')+'</p>';}
async function refreshOffline(){try{downloadState=await offlineStatus(manifest);if(!downloadState.supported)offlineError='This browser cannot save offline files. Open in Safari or Chrome.';}catch{offlineError='Cannot read offline storage. Try Safari or Chrome in normal mode.';}downloadBox();}
function render(){stopAudio();const tab=location.hash.slice(1)||'practice';for(const a of document.querySelectorAll('nav a')){a.classList.toggle('active',a.dataset.tab===tab);if(a.dataset.tab===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}document.querySelector('#saved-toggle').classList.toggle('marked',onlyBookmarks);if(tab==='dictionary')renderDictionary();else if(tab==='offline')void renderOffline();else renderPractice();}
function newSession(pool){if(!pool.length)return;const ids=makeSession(pool);session={ids,position:0,mode:settings.mode,responses:{},choices:ids.map(id=>makeChoices(byId.get(id),data.entries.filter(e=>e.module===byId.get(id).module)))};persistSession();render();}
function finishAnswer(correct){const r=currentResponse();r.correct=correct;r.checked=true;if(!r.recorded){recordAnswer(progress,currentEntry().id,correct,r.assisted);r.recorded=true;save('progress',progress);}persistSession();render();}
function toggleBookmark(id){if(bookmarks.has(id))bookmarks.delete(id);else bookmarks.add(id);save('bookmarks',[...bookmarks]);}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.speak){const e=byId.get(b.dataset.speak);if(!e)return;if(session?.mode==='spelling'&&currentEntry()?.id===e.id){currentResponse().assisted=true;persistSession();}if(audio?.dataset?.entry===e.id){stopAudio();return;}stopAudio();const clip=new Audio(e.audio);clip.dataset.entry=e.id;audio=clip;b.classList.add('playing');b.setAttribute('aria-pressed','true');clip.onended=()=>{if(audio===clip)stopAudio();};clip.onerror=()=>{if(audio===clip){stopAudio();status.textContent='Audio unavailable. Connect and download the offline pack, then try again.';}};try{await clip.play();status.textContent='';}catch{if(audio===clip){stopAudio();status.textContent='Could not play audio. Tap the speaker to try again.';}}return;}if(b.dataset.bookmark){toggleBookmark(b.dataset.bookmark);renderDictionary();return;}if(b.dataset.mode){settings.mode=b.dataset.mode;save('settings',settings);renderHome();return;}if(b.hasAttribute('data-choice')){const r=currentResponse();if(r.checked)return;r.answer=b.dataset.choice;finishAnswer(session.choices[session.position][Number(b.dataset.choice)].correct);return;}
const action=b.dataset.action;if(action==='start')newSession(selectEntries());if(action==='resume'){renderPractice();}if(action==='home'){stopAudio();renderHome();}if(action==='next'){session.position++;persistSession();render();main.focus();}if(action==='finish'){session=null;persistSession();render();}if(action==='retry'){const pool=session.ids.filter((id,i)=>!session.responses[i]?.correct||session.responses[i]?.assisted).map(id=>byId.get(id));newSession(pool);}if(action==='bookmark'){toggleBookmark(currentEntry().id);renderPractice();}if(action==='reveal'){const r=currentResponse();r.revealed=!r.revealed;r.assisted=true;persistSession();renderPractice();}if(action==='skip'){const r=currentResponse();if(!r.recorded){recordAnswer(progress,currentEntry().id,false,true);save('progress',progress);r.recorded=true;}session.position++;persistSession();render();}if(action==='unfilter'){onlyBookmarks=false;renderHome();}if(action==='verify-offline')await refreshOffline();if(action==='cancel-download'){cancelDownload();status.textContent='Pausing after current files finish…';}if(action==='download'){if(!('serviceWorker' in navigator)||!('caches' in globalThis)){offlineError='Offline access needs Safari or Chrome over HTTPS.';downloadBox();return;}downloadBusy=true;offlineError='';status.textContent='';downloadBox();try{downloadState=await downloadAll(manifest,(count,total)=>{downloadState={...downloadState,count,total};downloadBox();});}catch(error){offlineError=navigator.onLine?'Download interrupted. Check free space, then resume.':'You are offline. Connect and resume the download.';await refreshOffline();}finally{downloadBusy=false;downloadBox();}}if(action==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;document.querySelector('#install-area').innerHTML='';}});
document.addEventListener('submit',event=>{if(event.target.id!=='answer-form')return;event.preventDefault();const r=currentResponse();if(!r.answer.trim())return;finishAnswer(checkAnswer(currentEntry(),r.answer));});
document.addEventListener('input',event=>{if(event.target.id==='answer'){const r=currentResponse();r.answer=event.target.value;if(r.checked){r.checked=false;r.assisted=true;}persistSession();document.querySelector('#answer-form button').disabled=!r.answer.trim();}if(event.target.id==='search'){query=event.target.value;const pos=event.target.selectionStart;renderDictionary();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{if(event.target.id==='module'){settings.module=event.target.value;settings.section='all';save('settings',settings);if(location.hash==='#dictionary')renderDictionary();else renderHome();}if(event.target.id==='section'){settings.section=event.target.value;save('settings',settings);if(location.hash==='#dictionary')renderDictionary();else renderHome();}if(event.target.id==='review-only'){settings.review=event.target.checked;save('settings',settings);renderHome();}if(event.target.id==='bookmarks-only'){onlyBookmarks=event.target.checked;renderDictionary();}});
document.querySelector('#saved-toggle').innerHTML=icon('bookmark');document.querySelector('#saved-toggle').onclick=()=>{onlyBookmarks=!onlyBookmarks;if(location.hash!=='#dictionary')location.hash='dictionary';else render();};
for(const a of document.querySelectorAll('nav a'))a.innerHTML=icon(a.dataset.tab)+({practice:'Practice',dictionary:'Dictionary',offline:'Offline'}[a.dataset.tab]);
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});
try{const responses=await Promise.all([fetch('./data.json'),fetch('./audio-manifest.json')]);if(responses.some(r=>!r.ok))throw Error('Data unavailable');[data,manifest]=await Promise.all(responses.map(r=>r.json()));for(const e of data.entries)byId.set(e.id,e);progress=restoreProgress(localStorageSafe());bookmarks=new Set((Array.isArray(read('bookmarks',[]))?read('bookmarks',[]):[]).filter(id=>byId.has(id)));const savedSettings=read('settings',{});if(['all','1','2'].includes(savedSettings.module))settings.module=savedSettings.module;if(['recognition','spelling','listening'].includes(savedSettings.mode))settings.mode=savedSettings.mode;if(data.entries.some(e=>e.sectionId===savedSettings.section))settings.section=savedSettings.section;settings.review=savedSettings.review===true;session=restoreSession(read('session',null),byId);render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{if(location.hash==='#offline')refreshOffline();}).catch(()=>{status.textContent='Offline setup failed. Open this site in Safari or Chrome and reload.';});}catch(error){main.innerHTML='<h1>Let’s reconnect.</h1><p class="intro">Open the site with an internet connection once to save your wordbook.</p><button class="button" onclick="location.reload()">Try again</button>';}
function localStorageSafe(){try{return localStorage.getItem('sp-progress');}catch{return null;}}

function syncViewportHeight(){const v=window.visualViewport;if(!v||v.scale===1)document.documentElement.style.setProperty('--viewport-height',(v?.height||innerHeight)+'px');}
window.addEventListener('resize',syncViewportHeight);window.visualViewport?.addEventListener('resize',syncViewportHeight);syncViewportHeight();
